function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

const VALID_POSITIONS = new Set(['Top', 'Bottom', 'Left', 'Right']);

function parseVideoUrl(url) {
  if (!url) return null;
  const source = String(url);

  const youtubeMatch = source.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/embed\/)([a-zA-Z0-9_-]{6,})/);
  if (youtubeMatch) {
    return {
      platform: 'youtube',
      embedUrl: `https://www.youtube.com/embed/${youtubeMatch[1]}`,
      title: 'YouTube video player',
    };
  }

  const vimeoMatch = source.match(/vimeo\.com\/(?:video\/)?(\d+)/);
  if (vimeoMatch) {
    return {
      platform: 'vimeo',
      embedUrl: `https://player.vimeo.com/video/${vimeoMatch[1]}`,
      title: 'Vimeo video player',
    };
  }

  return null;
}

export default {
  async main(input = {}) {
    const {
      videoUrl = '',
      includeText = 'No',
      textPosition = 'Right',
      heading = '',
      body = '',
    } = input;

    const safePosition = VALID_POSITIONS.has(textPosition) ? textPosition : 'Right';
    const video = parseVideoUrl(videoUrl);

    const mediaHtml = video
      ? `<iframe class="video-embed__iframe" src="${esc(video.embedUrl)}" title="${esc(video.title)}" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>`
      : `<div class="video-embed__unavailable">
        <p class="video-embed__unavailable-title">Video unavailable</p>
        <p class="video-embed__unavailable-message">Enter a valid YouTube or Vimeo link.</p>
      </div>`;

    const showText = includeText === 'Yes' && (heading || body);
    const textHtml = showText
      ? `<div class="video-embed__text">
        ${heading ? `<h3 class="video-embed__heading" data-sq-field="heading">${esc(heading)}</h3>` : ''}
        ${body ? `<div class="video-embed__body" data-sq-field="body">${body}</div>` : ''}
      </div>`
      : '';

    return /*html*/`
<div class="video-embed" data-text-position="${esc(safePosition)}">
  <div class="video-embed__media">
    ${mediaHtml}
  </div>
  ${textHtml}
</div>
`;
  },
};
